import { useState } from 'react'

export function useActiveTerminal(workspaceId: string) {
  const key = `activeTerminal:${workspaceId}`
  const [active, setActive] = useState(() =>
    localStorage.getItem(key) ?? 'agent-1'
  )

  function selectTerminal(id: string) {
    localStorage.setItem(key, id)
    setActive(id)
  }

  return { active, selectTerminal }
}

