export function SessionTabs({ sessions, active, onSelect }) {
  return (
    <nav className="session-tabs" aria-label="Sessions">
      {sessions.map(session => (
        <button
          key={session.id}
          aria-pressed={session.id === active}
          onClick={() => onSelect(session.id)}
        >
          {session.title}
        </button>
      ))}
    </nav>
  )
}

